243	    background: var(--gradient-bg-dark);
244	  }
245	  :focus-visible {
246	    outline: 2px solid var(--primary);
247	    outline-offset: 3px;
248	    border-radius: var(--radius-sm);
249	  }
250	  @media (prefers-reduced-motion: reduce) {
251	    *, *::before, *::after {
252	      animation-duration: 0.01ms !important;
253	      transition-duration: 0.01ms !important;
254	    }
255	    html {
256	      scroll-behavior: auto;
257	    }
258	  }
259	}
260	
261	@layer components {
262	  /* ─── Liquid glass system ─── */
263	  .glass {
264	    backdrop-filter: blur(16px) saturate(180%);
265	    -webkit-backdrop-filter: blur(16px) saturate(180%);
266	    background: var(--glass-bg);
267	    border: 1px solid var(--glass-border);
268	    box-shadow:
269	      0 8px 32px var(--glass-shadow),
270	      inset 0 1px 0 rgba(255, 255, 255, 0.15),
271	      inset 0 -1px 0 rgba(0, 0, 0, 0.08);
272	    border-radius: var(--radius-xl);
273	  }
274	
275	  .glass-elevated {
276	    backdrop-filter: blur(24px) saturate(200%);
277	    -webkit-backdrop-filter: blur(24px) saturate(200%);
278	    background: var(--glass-bg);
279	    border: 1px solid var(--glass-border);
280	    box-shadow:
281	      0 20px 60px var(--glass-shadow),
282	      inset 0 2px 0 rgba(255, 255, 255, 0.20),
283	      inset 0 -1px 0 rgba(0, 0, 0, 0.12);
284	    border-radius: var(--radius-2xl);
285	  }
286	
287	  .glass-nav {
288	    backdrop-filter: blur(20px) saturate(160%);
289	    -webkit-backdrop-filter: blur(20px) saturate(160%);
290	    background: var(--glass-bg);
291	    border-bottom: 1px solid var(--glass-border);
292	    box-shadow: 0 1px 0 var(--glass-border), 0 4px 20px var(--glass-shadow);
293	  }
294	
295	  .glass-card {
296	    backdrop-filter: blur(12px) saturate(150%);
297	    -webkit-backdrop-filter: blur(12px) saturate(150%);
298	    background: var(--glass-bg);
299	    border: 1px solid var(--glass-border);
300	    box-shadow:
301	      0 4px 24px var(--glass-shadow),
302	      inset 0 1px 0 rgba(255, 255, 255, 0.12);
303	    border-radius: var(--radius-lg);
304	    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
305	  }
306	
307	  .glass-card:hover {
308	    border-color: var(--primary);
309	    box-shadow:
310	      0 8px 40px var(--glass-shadow),
311	      0 0 0 1px var(--primary),
312	      inset 0 1px 0 rgba(255, 255, 255, 0.20);
313	    transform: translateY(-2px);
