'use client'

import { useState, useEffect } from 'react'
import Link from 'next/link'
import { ChevronDown, Menu, X } from 'lucide-react'
import ThemeToggle from '@/components/theme-toggle'
import { cn } from '@/lib/utils'

const productLinks = [
  { name: 'Work', href: '#outcomes' },
  { name: 'Systems', href: '#how-it-works' },
  { name: 'Gallery', href: '#gallery' },
]

const resourceLinks = [
  { name: 'Essays', href: '/essays' },
  { name: 'Now', href: '/now' },
  { name: 'Community', href: '/community' },
  { name: 'FAQ', href: '#faq' },
]

function scrollTo(href: string, close?: () => void) {
  if (href.startsWith('#')) {
    const el = document.getElementById(href.slice(1))
    if (el) window.scrollTo({ top: el.offsetTop - 80, behavior: 'smooth' })
    close?.()
    return
  }
}

type DropdownProps = {
  label: string
  links: { name: string; href: string }[]
  onNavigate: (href: string) => void
}

function NavDropdown({ label, links, onNavigate }: DropdownProps) {
  const [open, setOpen] = useState(false)
  return (
    <div
      className="relative"
      onMouseEnter={() => setOpen(true)}
      onMouseLeave={() => setOpen(false)}
    >
      <button
        type="button"
        className="flex items-center gap-1 text-sm text-muted-foreground hover:text-primary transition-colors py-2"
        onClick={() => setOpen(!open)}
      >
        {label}
        <ChevronDown size={14} className={cn('transition-transform', open && 'rotate-180')} />
      </button>
      {open && (
        <div className="absolute top-full left-0 pt-1 min-w-[180px] z-50">
          <div className="rounded-xl border border-border bg-card/95 backdrop-blur-md shadow-lg p-2">
            {links.map((link) =>
              link.href.startsWith('/') ? (
                <Link
                  key={link.name}
                  href={link.href}
                  className="block px-3 py-2 text-sm rounded-lg hover:bg-primary/5 hover:text-primary"
                  onClick={() => setOpen(false)}
                >
                  {link.name}
                </Link>
              ) : (
                <button
                  key={link.name}
                  type="button"
                  onClick={() => {
                    onNavigate(link.href)
                    setOpen(false)
                  }}
                  className="w-full text-left px-3 py-2 text-sm rounded-lg hover:bg-primary/5 hover:text-primary"
                >
                  {link.name}
                </button>
              ),
            )}
          </div>
        </div>
      )}
    </div>
  )
}

export default function LandingNav() {
  const [isScrolled, setIsScrolled] = useState(false)
  const [mobileOpen, setMobileOpen] = useState(false)

  useEffect(() => {
    const onScroll = () => setIsScrolled(window.scrollY > 40)
    window.addEventListener('scroll', onScroll)
    return () => window.removeEventListener('scroll', onScroll)
  }, [])

  useEffect(() => {
    document.body.style.overflow = mobileOpen ? 'hidden' : ''
    return () => {
      document.body.style.overflow = ''
    }
  }, [mobileOpen])

  const navigate = (href: string) => scrollTo(href, () => setMobileOpen(false))

  return (
    <>
      <header
        className={cn(
          'fixed top-0 inset-x-0 z-50 transition-all duration-300',
          isScrolled ? 'glass-nav py-2 border-b border-border/50' : 'bg-transparent py-4',
        )}
      >
        <nav className="landing-container flex items-center justify-between h-14">
          <button
            type="button"
            onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
            className="font-mono text-xl font-bold text-primary"
          >
            K.
          </button>

          <div className="hidden lg:flex items-center gap-6">
            <NavDropdown label="Work" links={productLinks} onNavigate={navigate} />
            <NavDropdown label="Writing" links={resourceLinks} onNavigate={navigate} />
          </div>

          <div className="flex items-center gap-2">
            <ThemeToggle />
            <button
              type="button"
              onClick={() => navigate('#contact')}
              className="hidden sm:inline-flex pill pill-ink text-sm"
            >
              Get in touch
            </button>
            <button
              type="button"
              className="lg:hidden p-2 text-muted-foreground"
              onClick={() => setMobileOpen(!mobileOpen)}
              aria-label="Menu"
            >
              {mobileOpen ? <X size={22} /> : <Menu size={22} />}
            </button>
          </div>
        </nav>
      </header>

      {mobileOpen && (
        <div className="fixed inset-0 z-40 lg:hidden bg-background/98 backdrop-blur-md pt-20 px-6 overflow-y-auto">
          <div className="space-y-6 max-w-sm mx-auto">
            {[
              { title: 'Work', links: productLinks },
              { title: 'Writing', links: resourceLinks },
            ].map((group) => (
              <div key={group.title}>
                <p className="text-[10px] font-mono uppercase tracking-widest text-muted-foreground mb-2">
                  {group.title}
                </p>
                <div className="space-y-1">
                  {group.links.map((link) =>
                    link.href.startsWith('/') ? (
                      <Link
                        key={link.name}
                        href={link.href}
                        className="block py-2 text-lg"
                        onClick={() => setMobileOpen(false)}
                      >
                        {link.name}
                      </Link>
                    ) : (
                      <button
                        key={link.name}
                        type="button"
                        className="block py-2 text-lg text-left w-full"
                        onClick={() => navigate(link.href)}
                      >
                        {link.name}
                      </button>
                    ),
                  )}
                </div>
              </div>
            ))}
            <button type="button" className="btn-primary w-full" onClick={() => navigate('#contact')}>
              Get in touch
            </button>
          </div>
        </div>
      )}
