import { execSync } from 'node:child_process'
import { existsSync, readFileSync, unlinkSync } from 'node:fs'
import path from 'node:path'

const envFile = path.join(process.cwd(), 'scripts', 'turso-prod.env')
if (existsSync(envFile)) {
  for (const line of readFileSync(envFile, 'utf-8').split('\n')) {
    const trimmed = line.trim()
    if (!trimmed || trimmed.startsWith('#')) continue
    const eq = trimmed.indexOf('=')
    if (eq === -1) continue
    const key = trimmed.slice(0, eq)
    const value = trimmed.slice(eq + 1)
    if (!process.env[key]) process.env[key] = value
  }
}

const dbName = process.env.TURSO_DB_NAME ?? 'kennedy-portfolio'
const schemaFile = path.join(process.cwd(), 'prisma', '.turso-schema.sql')

function main() {
  console.log('Generating schema SQL…')
  execSync(
    `npx prisma migrate diff --from-empty --to-schema prisma/schema.prisma --script -o ${schemaFile}`,
    { stdio: 'inherit', cwd: process.cwd() },
  )

  console.log(`Applying schema to Turso database "${dbName}" via CLI…`)
  try {
    execSync(`turso db shell ${dbName} < ${schemaFile}`, {
      stdio: 'inherit',
      shell: '/bin/bash',
      env: { ...process.env, PATH: `${process.env.HOME}/.turso:${process.env.PATH}` },
    })
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err)
    if (!msg.includes('already exists')) throw err
    console.log('Some objects already exist — continuing.')
  } finally {
    unlinkSync(schemaFile)
  }

  if (!process.env.DATABASE_URL?.startsWith('libsql://') || !process.env.DATABASE_AUTH_TOKEN) {
    console.error('Set DATABASE_URL (libsql://…) and DATABASE_AUTH_TOKEN in the environment before seeding.')
    process.exit(1)
  }

  console.log('Running seed against Turso…')
  execSync('npm run db:seed', { stdio: 'inherit', env: process.env })
  console.log('Turso sync complete.')
}

try {
  main()
} catch (err) {
  console.error(err)
  process.exit(1)
}
