'use client'

import { useEffect, useRef, useState } from 'react'

function parseStatValue(value: string | null | undefined): { target: number; suffix: string } | null {
  if (typeof value !== 'string' || value.length === 0) return null
  const match = value.match(/^(\d+)(.*)$/)
  if (!match) return null
  const target = parseInt(match[1], 10)
  if (Number.isNaN(target)) return null
  return { target, suffix: match[2] ?? '' }
}

export function AnimatedStat({ value }: { value?: string | null }) {
  const ref = useRef<HTMLSpanElement>(null)

  // Initial paint shows the final value so SSR markup matches hydration and
  // the number is never stuck at 0 if JS fails — we only animate the reveal.
  const [display, setDisplay] = useState<string>(() => (typeof value === 'string' ? value : ''))

  useEffect(() => {
    // Depend on the raw string only: parseStatValue returns a new object each
    // render, and putting it in the deps restarted the count on *every*
    // parent re-render — the visible "fumbling" counter.
    const parsed = parseStatValue(value)
    if (!parsed || typeof window === 'undefined') return
    const { target, suffix } = parsed

    const el = ref.current
    if (!el || typeof IntersectionObserver === 'undefined') return

    const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches
    const run = () => {
      if (prefersReduced) {
        setDisplay(`${target}${suffix}`)
        return
      }
      const duration = 1200
      const startTime = performance.now()
      let raf = 0
      const tick = (now: number) => {
        const progress = Math.min((now - startTime) / duration, 1)
        const eased = 1 - Math.pow(1 - progress, 3)
        setDisplay(`${Math.round(target * eased)}${suffix}`)
        if (progress < 1) raf = requestAnimationFrame(tick)
      }
      raf = requestAnimationFrame(tick)
    }

    // Animate once, when the number first enters the viewport.
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((e) => e.isIntersecting)) {
          observer.disconnect()
          run()
        }
      },
      { threshold: 0.4 },
    )
    observer.observe(el)
    return () => {
      observer.disconnect()
      // No raf id leak when unmounting mid-animation.
      cancelAnimationFrame(raf)
    }
  }, [value])

  if (typeof value !== 'string') return <span>{''}</span>
  return <span ref={ref}>{display}</span>
}

