'use client'

import { useEffect, useState } from 'react'
import { useTheme } from 'next-themes'
import { Sun, Moon } from 'lucide-react'
import { motion } from 'framer-motion'
import { iconHover } from '@/lib/motion'
import { cn } from '@/lib/utils'

export default function AdminThemeToggle({ className }: { className?: string }) {
  const { theme, setTheme } = useTheme()
  const [mounted, setMounted] = useState(false)

  useEffect(() => setMounted(true), [])

  if (!mounted) {
    return <div className={cn('w-9 h-9 rounded-lg', className)} aria-hidden />
  }

  const isDark = theme === 'dark'

  return (
    <motion.button
      type="button"
      {...iconHover}
      onClick={() => setTheme(isDark ? 'light' : 'dark')}
      className={cn('admin-theme-toggle', className)}
      aria-label={`Switch to ${isDark ? 'light' : 'dark'} mode`}
      title={`Switch to ${isDark ? 'light' : 'dark'} mode`}
    >
      {isDark ? <Sun size={16} /> : <Moon size={16} />}
    </motion.button>
  )
}

