'use client'

type StartViewTransitionDocument = Document & {
  startViewTransition?: (update: () => void) => { ready: Promise<void> }
}

/**
 * Switch theme with a circular reveal expanding from the toggle button
 * (View Transitions API), falling back to a short global crossfade where the
 * API or reduced-motion preference rules it out. Keeps both toggles — public
 * nav and admin header — on one consistent, smooth mechanism.
 */
export async function switchTheme(
  apply: () => void,
  next: 'light' | 'dark',
  origin?: { x: number; y: number },
) {
  const root = document.documentElement

  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    apply()
    return
  }

  const doc = document as StartViewTransitionDocument
  const x = origin?.x ?? window.innerWidth - 48
  const y = origin?.y ?? 40
  const radius = Math.hypot(Math.max(x, window.innerWidth - x), Math.max(y, window.innerHeight - y))

  if (typeof doc.startViewTransition === 'function') {
    // Isolate the snapshot so the reveal reads as one clean sweep.
    root.classList.add('theme-vt')
    const transition = doc.startViewTransition(apply)
    try {
      await transition.ready
      root.animate(
        { clipPath: [`circle(0px at ${x}px ${y}px)`, `circle(${radius}px at ${x}px ${y}px)`] },
        { duration: 450, easing: 'cubic-bezier(0.22, 1, 0.36, 1)', pseudoElement: '::view-transition-new(root)' },
      )
    } finally {
      await transition.finished.catch(() => {})
      root.classList.remove('theme-vt')
    }
    return
  }

  // Fallback: brief global color crossfade, applied only while switching.
  root.classList.add('theme-switching')
  try {
    apply()
  } finally {
    window.setTimeout(() => root.classList.remove('theme-switching'), 350)
  }
}

