@layer components {
  /* ═══ Editorial system — borrowed patterns, TIC paper/ink voice ═══ */

  /* Running-head label: "01 / selected work" etc. */
  .label-mono {
    @apply font-mono uppercase;
    font-size: 0.6875rem;
    letter-spacing: 0.22em;
    color: var(--text-muted);
  }

  /* Chapter header: marker left, hairline filling the rest */
  .chapter-header {
    @apply flex items-center gap-4 mb-10 sm:mb-14;
  }

  /* Six faint vertical hairlines behind the hero, fading downward */
  .rule-grid {
    background-image: linear-gradient(to right, var(--border) 0 1px, transparent 1px);
    background-size: calc(100% / 6) 100%;
    -webkit-mask-image: linear-gradient(to bottom, black 30%, transparent 92%);
    mask-image: linear-gradient(to bottom, black 30%, transparent 92%);
  }

  /* Fixed-nav scrim: content scrolls under a fading veil — no JS */
  .nav-scrim {
    background: linear-gradient(
      to bottom,
      var(--background) 0%,
      color-mix(in srgb, var(--background) 82%, transparent) 55%,
      transparent 100%
    );
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
    -webkit-mask-image: linear-gradient(to bottom, black 42%, transparent);
    mask-image: linear-gradient(to bottom, black 42%, transparent);
  }

  /* Accent period-dot that ends display headlines */
  .accent-dot {
    display: inline-block;
    width: 0.115em;
    height: 0.115em;
    border-radius: 9999px;
    background: var(--primary);
    margin-left: 0.06em;
    vertical-align: baseline;
  }

  /* Hairline list row (writing index, FAQ) */
  .row-line {
    @apply flex items-baseline justify-between gap-6 py-4 border-b transition-colors duration-200;
    border-color: color-mix(in srgb, var(--border) 70%, transparent);
  }
  .row-line:hover {
    border-color: color-mix(in srgb, var(--foreground) 28%, transparent);
  }

  /* Availability ping dot (hero status line) */
  .ping-dot {
    position: relative;
    display: inline-flex;
    width: 6px;
    height: 6px;
  }
  .ping-dot::before,
  .ping-dot::after {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: 9999px;
    background: var(--primary);
  }
  .ping-dot::before {
    animation: ping-fade 2s cubic-bezier(0, 0, 0.2, 1) infinite;
  }
  @keyframes ping-fade {
    75%, 100% {
      transform: scale(2.4);
      opacity: 0;
    }
  }

  /* Odometer digit column */
  .odometer-window {
    display: inline-block;
    overflow: hidden;
    height: 1em;
    line-height: 1;
    font-variant-numeric: tabular-nums;
  }
  .odometer-column {
    display: flex;
    flex-direction: column;
    transform: translateY(-10%);
    transition: transform 900ms cubic-bezier(0.22, 1, 0.36, 1);
  }
  .odometer-column > span {
    height: 1em;
    line-height: 1;
  }

  /* Marquee pause on hover/focus */
  .marquee-track:hover,
  .marquee-track:focus-within {
    animation-play-state: paused;
  }
}

