function parseStatValue(value: string | null | undefined): { digits: number[]; suffix: string } | null {
  if (typeof value !== 'string' || value.length === 0) return null
  const match = value.match(/^(\d+)(.*)$/)
  if (!match) return null
  return {
    digits: match[1].split('').map((d) => parseInt(d, 10)),
    suffix: match[2] ?? '',
  }
}

/**
 * Rolling-digit odometer. Each digit rides a 0–9 column that settles with a
 * long out-curve and a small per-column stagger, armed once when the number
 * enters the viewport. Falls back to plain text under reduced motion.
 */
export function Odometer({ value, minDigits = 2 }: { value?: string | null; minDigits?: number }) {
  const ref = useRef<HTMLSpanElement>(null)
  const [armed, setArmed] = useState(false)

  const parsed = parseStatValue(value)
  const digits = parsed?.digits ?? []
  const padded = digits.length < minDigits
    ? Array.from({ length: minDigits - digits.length }, () => 0).concat(digits)
    : digits

  useEffect(() => {
    const el = ref.current
    if (!el || typeof IntersectionObserver === 'undefined') {
      setArmed(true)
      return
    }
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((e) => e.isIntersecting)) {
          observer.disconnect()
          // Next frame so the 0-position is painted once before it rolls.
          requestAnimationFrame(() => setArmed(true))
        }
      },
      { threshold: 0.6 },
    )
    observer.observe(el)
    return () => observer.disconnect()
  }, [])

