  const reduced =
    typeof window !== 'undefined' &&
    window.matchMedia('(prefers-reduced-motion: reduce)').matches

  return (
    <span ref={ref} role="text" aria-label={value ?? ''} className="inline-flex items-baseline">
      {(reduced ? padded : padded).map((digit, i) => (
