'use client'

import Link from 'next/link'
import { ArrowUpRight } from 'lucide-react'
import { motion } from 'framer-motion'
import type { Essay } from '@prisma/client'

function formatDate(date: Date | null) {
  if (!date) return ''
  return new Intl.DateTimeFormat('en-GB', {
    day: 'numeric',
    month: 'long',
    year: 'numeric',
  }).format(new Date(date))
}

export default function WritingRows({ essays, max = 5 }: { essays: Essay[]; max?: number }) {
  const published = essays.slice(0, max)
  if (published.length === 0) return null

  return (
    <div>
      <motion.p
        className="label-mono mb-6"
        initial={{ opacity: 0 }}
        whileInView={{ opacity: 1 }}
        viewport={{ once: true }}
      >
        03 / writing
      </motion.p>
      <div>
        {published.map((essay) => (
          <motion.div
            key={essay.id}
            initial={{ opacity: 0, y: 10 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true, margin: '-40px' }}
            transition={{ duration: 0.4 }}
          >
            <Link href={`/essays/${essay.slug}`} className="row-line group">
              <span className="text-[15px] sm:text-base text-muted-foreground group-hover:text-foreground transition-colors duration-200 text-balance">
                {essay.title}
              </span>
              <span className="flex items-center gap-3 shrink-0 label-mono !tracking-normal">
                <span className="hidden sm:inline">{formatDate(essay.publishedAt)}</span>
                <ArrowUpRight
                  size={14}
                  className="opacity-0 -translate-x-1 translate-y-1 group-hover:opacity-100 group-hover:translate-x-0.5 group-hover:-translate-y-0.5 transition-all duration-200"
                />
              </span>
            </Link>
          </motion.div>
        ))}
      </div>
      <Link
        href="/essays"
        className="mt-6 inline-flex items-center gap-1.5 font-mono text-sm text-primary hover:underline"
      >
        all essays <ArrowUpRight size={13} />
      </Link>
    </div>
  )
}

