input.content:
'use client'

import { useRef, useState } from 'react'
import { motion, useReducedMotion } from 'framer-motion'
import { ArrowUpRight, Check } from 'lucide-react'
import Reveal from '@/components/landing/reveal'
import { LINKS } from '@/lib/links'

const CONTACT_EMAIL = 'kenhopkins.ke@gmail.com'

function MaskLine({
  text,
  muted,
  delay = 0,
}: {
  text: string
  muted?: boolean
  delay?: number
}) {
  const reduced = useReducedMotion()
  return (
    <span className="block overflow-hidden">
      {/* Screen readers get the plain sentence; the letters are decoration. */}
      <span className="sr-only">{text}</span>
      <span aria-hidden className="flex">
        {Array.from(text).map((ch, i) =>
          ch === ' ' ? (
            <span key={i} className="w-[0.28em]" />
          ) : (
            <motion.span
              key={i}
              aria-hidden
              className={`inline-block ${muted ? 'text-landing-muted' : ''}`}
              initial={{ y: reduced ? 0 : '110%' }}
              whileInView={{ y: 0 }}
              viewport={{ once: true, margin: '-80px' }}
              transition={{ duration: 0.6, ease: [0.22, 1, 0.36, 1], delay: delay + i * 0.022 }}
            >
              {ch}
            </motion.span>
          ),
        )}
      </span>
    </span>
  )
}

export default function CtaFinal() {
  const [copied, setCopied] = useState(false)
  const revert = useRef<ReturnType<typeof setTimeout> | null>(null)

  const copyEmail = async () => {
    try {
      await navigator.clipboard.writeText(CONTACT_EMAIL)
      setCopied(true)
      if (revert.current) clearTimeout(revert.current)
      revert.current = setTimeout(() => setCopied(false), 2000)
    } catch {
      window.location.href = `mailto:${CONTACT_EMAIL}`
    }
  }

  const scrollToContact = () => {
    const el = document.getElementById('contact')
    if (el) window.scrollTo({ top: el.offsetTop - 80, behavior: 'smooth' })
  }

  return (
    <section aria-label="Next" className="border-t">
      <div className="landing-container pt-24 sm:pt-36 pb-20 sm:pb-28">
        <Reveal>
          <p className="label-mono mb-10">04 / next</p>
        </Reveal>

        <h2 className="font-display font-medium leading-[0.98] tracking-[-0.03em] text-[clamp(2.5rem,7.5vw,5.75rem)]">
          <MaskLine text="let's build" />
          <MaskLine text="what's next" muted delay={0.18} />
          <span className="sr-only">.</span>
          <span aria-hidden className="accent-dot inline-block align-baseline" style={{ width: '0.09em', height: '0.09em' }} />
        </h2>

        <Reveal className="mt-12 flex flex-wrap items-center gap-4">
          <button type="button" onClick={copyEmail} className="btn-ghost !rounded-full inline-flex items-center gap-2.5">
            <span className="ping-dot" aria-hidden />
            {copied ? (
              <>
                copied <Check size={14} className="text-primary" />
              </>
            ) : (
              <>copy email</>
            )}
          </button>
          <button type="button" onClick={scrollToContact} className="btn-primary !rounded-full inline-flex items-center gap-2">
            start a conversation
            <ArrowUpRight size={15} />
          </button>
          <a
            href={LINKS.linktree}
            target="_blank"
            rel="noopener noreferrer"
            className="label-mono hover:!text-primary transition-colors ml-1"
          >
            all my links ↗
          </a>
        </Reveal>
      </div>
    </section>
  )
}

