              {mobileOpen ? <X size={22} /> : <Menu size={22} />}
            </button>
          </div>
        </nav>
      </header>

      {mobileOpen && (
        <div className="fixed inset-0 z-30 lg:hidden bg-background pt-24 px-8 overflow-y-auto">
          <div className="space-y-7 max-w-sm">
            {links.map((l) => (
