        type="button"
        onClick={() => setOpen(!open)}
        className="w-full flex items-center justify-between py-5 text-left font-medium hover:text-primary transition-colors"
      >
        {q}
        {open ? <ChevronUp size={18} /> : <ChevronDown size={18} />}
      </button>
      {open && <p className="pb-5 text-sm text-landing-muted leading-relaxed">{a}</p>}
    </div>
  )
}

export default function FaqSection({ faqs }: { faqs: FAQ[] }) {
  if (faqs.length === 0) return null

  return (
    <section id="faq" className="landing-section">
      <div className="landing-container max-w-3xl">
        <Reveal>
          <p className="text-[10px] font-mono uppercase tracking-widest text-primary mb-2">
            FAQ
          </p>
          <h2 className="font-display text-3xl font-bold tracking-tight mb-8">
            Common questions
          </h2>
        </Reveal>
        <div className="rounded-2xl border border-border bg-card px-6">
          {faqs.map((faq) => (
            <FaqItem key={faq.id} q={faq.question} a={faq.answer} />
          ))}
        </div>
      </div>
    </section>
  )
}

