import { prisma } from '@/lib/db'
import type { Project, Testimonial, ServiceTier, ServiceAddon, FAQ, SiteStat, NowPage, GalleryImage } from '@prisma/client'

export type GalleryPhotoDTO = {
  id: string
  src: string
  caption: string
  location?: string | null
  date?: string | null
  category: string
}

export const galleryCategories = ['All', 'Tech Event', 'Community', 'Life'] as const
export type GalleryCategory = (typeof galleryCategories)[number]

export type ProjectDTO = Omit<Project, 'techStack'> & { tech: string[] }
export type ServiceTierDTO = Omit<ServiceTier, 'features'> & { features: string[] }
export type NowPageDTO = Omit<NowPage, 'building' | 'learning' | 'reading'> & {
  building: string[]
  learning: string[]
  reading: string[]
}

function parseJsonArray(raw: unknown): string[] {
  if (Array.isArray(raw)) return raw.map(String)
  if (typeof raw !== 'string') return []
  try {
    const value = JSON.parse(raw) as unknown
    return Array.isArray(value) ? value.map(String) : []
  } catch {
    return []
  }
}

function parseProject(p: Project): ProjectDTO {
  const { techStack, ...rest } = p
  return { ...rest, tech: parseJsonArray(techStack) }
}

function parseTier(t: ServiceTier): ServiceTierDTO {
  const { features, ...rest } = t
  return { ...rest, features: parseJsonArray(features) }
}

export async function getProjects() {
  const rows = await prisma.project.findMany({ orderBy: { order: 'asc' } })
  return rows.map(parseProject)
}

export async function getTestimonials() {
  return prisma.testimonial.findMany({ orderBy: { order: 'asc' } })
}

export async function getServices() {
  const [tiers, addons, faqs] = await Promise.all([
    prisma.serviceTier.findMany({ orderBy: { order: 'asc' } }),
    prisma.serviceAddon.findMany({ orderBy: { order: 'asc' } }),
    prisma.fAQ.findMany({ where: { section: 'general' }, orderBy: { order: 'asc' } }),
  ])
  return {
    tiers: tiers.map(parseTier),
    addons,
    faqs,
  }
}

export async function getCommunityFaqs() {
  return prisma.fAQ.findMany({ where: { section: 'community' }, orderBy: { order: 'asc' } })
}

export async function getSiteStats() {
  return prisma.siteStat.findMany()
}

export async function getStatMap() {
  const stats = await getSiteStats()
  return Object.fromEntries(stats.map((s) => [s.key, s])) as Record<string, SiteStat>
}

export async function getNowPage(): Promise<NowPageDTO | null> {
  const row = await prisma.nowPage.findFirst({ orderBy: { updatedAt: 'desc' } })
  if (!row) return null
  return {
    ...row,
    building: parseJsonArray(row.building),
    learning: parseJsonArray(row.learning),
    reading: parseJsonArray(row.reading),
  }
}

export async function getPublishedEssays() {
  return prisma.essay.findMany({
    where: { status: 'published' },
    orderBy: { publishedAt: 'desc' },
  })
}

export async function getEssayBySlug(slug: string) {
  return prisma.essay.findFirst({ where: { slug, status: 'published' } })
}

export async function getCommunitySettings() {
  const rows = await prisma.siteSettings.findMany({
    where: { key: { in: ['ic_tagline', 'ic_quote'] } },
  })
  return Object.fromEntries(rows.map((r) => [r.key, r.value])) as Record<string, string>
}

export async function getMemberCount() {
  const stat = await prisma.siteStat.findUnique({ where: { key: 'community_members' } })
  // '0' is truthful while the first circle convenes; UI hides numeric claims
  // until a real count exists.
  return stat?.value ?? '0'
}

export async function getGalleryImages(): Promise<GalleryPhotoDTO[]> {
  const rows = await prisma.galleryImage.findMany({
    where: { visible: true },
    orderBy: { order: 'asc' },
  })
  return rows.map(parseGalleryImage)
}

function parseGalleryImage(img: GalleryImage): GalleryPhotoDTO {
  return {
    id: img.id,
    src: img.imageUrl,
    caption: img.caption ?? '',
    location: img.location,
    date: img.date,
    category: img.category,
  }
}

export type AboutPageDTO = {
  paragraphs: string[]
  skills: string[]
  profileImageUrl: string
}

export type ExperienceDTO = {
  id: string
  company: string
  title: string
  period: string
  url: string
  points: string[]
  order: number
}

export async function getAboutPage(): Promise<AboutPageDTO | null> {
  const row = await prisma.aboutPage.findUnique({ where: { id: 'main' } })
  if (!row) return null
  return {
    paragraphs: parseJsonArray(row.paragraphs),
    skills: parseJsonArray(row.skills),
    profileImageUrl: row.profileImageUrl || '/images/profile.jpg',
  }
}

export async function getExperienceEntries(): Promise<ExperienceDTO[]> {
  const rows = await prisma.experienceEntry.findMany({ orderBy: { order: 'asc' } })
  return rows.map((row) => ({
    id: row.id,
    company: row.company,
    title: row.title,
    period: row.period,
    url: row.url,
    points: parseJsonArray(row.points),
    order: row.order,
  }))
}

export async function getHomePageData() {
  const [projects, testimonials, services, stats, communitySettings, memberCount, gallery, about, experience, social] =
    await Promise.all([
      getProjects(),
      getTestimonials(),
      getServices(),
      getStatMap(),
      getCommunitySettings(),
      getMemberCount(),
      getGalleryImages(),
      getAboutPage(),
      getExperienceEntries(),
      import('@/lib/social').then((m) => m.getSocialData()),
    ])
  return { projects, testimonials, services, stats, communitySettings, memberCount, gallery, about, experience, social }
}

