import fs from "fs";
import path from "path";
import matter from "gray-matter";

const contentDir = path.join(process.cwd(), "content");

export interface DocMeta {
  slug: string;
  title: string;
  date?: string;
  summary?: string;
  state?: string;
  tag?: string;
}

function readDir(type: "journal" | "work" | "now"): string[] {
  const dir = path.join(contentDir, type);
  if (!fs.existsSync(dir)) return [];
  return fs
    .readdirSync(dir)
    .filter((f) => f.endsWith(".mdx") || f.endsWith(".md"));
}

export function getAllDocs(type: "journal" | "work" | "now"): DocMeta[] {
  return readDir(type)
    .map((file) => {
      const slug = file.replace(/\.mdx?$/, "");
      const raw = fs.readFileSync(path.join(contentDir, type, file), "utf8");
