import Link from "next/link";
import { getAllDocs, type DocMeta } from "@/lib/content";
import { FadeIn } from "@/components/FadeIn";

function Row({ href, doc }: { href: string; doc: DocMeta }) {
  return (
    <Link href={href} className="row-line group">
      <span className="text-lg text-ink/70 group-hover:text-accent transition-colors duration-500">
        {doc.title}
      </span>
      <span className="shrink-0 text-[0.7rem] uppercase tracking-[0.16em] text-ink/35 group-hover:text-accent/80 transition-colors duration-500">
        {doc.tag ?? (doc.state ? `${doc.state}` : "")}{" "}
        {doc.date ?? ""}
      </span>
    </Link>
  );
}

/**
 * The living index — real pieces, listed plainly.
 * Evidence instead of description: what the circle has actually made,
 * shown while it is still becoming.
 */
export function LivingIndex() {
  const journal = getAllDocs("journal").slice(0, 2);
  const work = getAllDocs("work").slice(0, 1);
  if (journal.length === 0 && work.length === 0) return null;

  return (
    <div className="mt-6">
      <FadeIn>
        <p className="text-[0.7rem] uppercase tracking-[0.18em] text-ink/35 mb-2">
          From the rooms, recently
        </p>
      </FadeIn>
      <div>
        {work.map((d) => (
          <FadeIn key={`work-${d.slug}`}>
            <Row href={`/work/${d.slug}`} doc={d} />
          </FadeIn>
        ))}
        {journal.map((d) => (
          <FadeIn key={`journal-${d.slug}`}>
            <Row href={`/journal/${d.slug}`} doc={d} />
          </FadeIn>
        ))}
      </div>
      <FadeIn>
        <div className="flex flex-wrap gap-x-8 mt-5 text-[0.7rem] uppercase tracking-[0.16em] text-ink/40">
          <Link href="/journal" className="hover:text-accent transition-colors duration-500">
            the whole journal →
          </Link>
          <Link href="/work" className="hover:text-accent transition-colors duration-500">
            all living work →
          </Link>
        </div>
      </FadeIn>
    </div>
  );
}

