'use client'

import Link from 'next/link'
import { trustLogos } from '@/data/trust-logos'

export default function TrustMarquee() {
  // One duplicated track inside a w-max flex = a seamless -50% loop.
  const track = [...trustLogos, ...trustLogos]

  return (
    <section
      className="border-b border-border py-7 overflow-hidden"
      aria-label="Projects shipped"
    >
      <div className="relative flex">
        <div className="marquee-track flex w-max items-center animate-marquee">
          {track.map((logo, i) => (
            <span key={`${logo.slug}-${i}`} className="flex items-center whitespace-nowrap">
              {logo.href ? (
                <a
                  href={logo.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="font-mono text-xs uppercase tracking-[0.18em] text-muted-foreground hover:text-primary transition-colors px-6"
                >
                  {logo.name}
                </a>
              ) : (
                <span className="font-mono text-xs uppercase tracking-[0.18em] text-muted-foreground px-6">
                  {logo.name}
                </span>
              )}
              <span aria-hidden className="text-primary/60 text-[8px]">◆</span>
            </span>
          ))}
        </div>
      </div>
    </section>
  )
}

'use client'

import Image from 'next/image'
import type { AboutPageDTO } from '@/lib/queries'
import Reveal from '@/components/landing/reveal'

export default function AboutLede({ about }: { about: AboutPageDTO | null }) {
  if (!about || about.paragraphs.length === 0) return null

  const [lede, ...rest] = about.paragraphs.filter(Boolean)
  if (!lede) return null

  return (
    <div>
      <Reveal>
        <p className="label-mono mb-6">02 / about</p>
        <div className="grid lg:grid-cols-[1fr_auto] gap-8 items-start">
          <p className="font-display text-xl sm:text-2xl leading-relaxed text-foreground max-w-3xl text-pretty">
            {lede}
          </p>
          <div className="relative h-28 w-28 shrink-0 overflow-hidden rounded-full border border-border ring-1 ring-foreground/5 hidden sm:block">
            {about.profileImageUrl && !['/images/profile.svg', '/images/profile.jpg'].includes(about.profileImageUrl) ? (
              <Image src={about.profileImageUrl} alt="Kennedy Muritu" fill sizes="112px" className="object-cover object-top" />
            ) : (
              <>
                <Image src="/images/profile-light.svg" alt="Kennedy Muritu" fill sizes="112px" className="object-cover object-top dark:hidden" />
                <Image src="/images/profile-dark.svg" alt="Kennedy Muritu" fill sizes="112px" className="hidden object-cover object-top dark:block" />
              </>
            )}
          </div>
        </div>
      </Reveal>

      {rest.length > 0 && (
        <Reveal className="mt-6 grid md:grid-cols-2 gap-8 max-w-4xl">
          {rest.map((p, i) => (
            <p key={i} className="text-[15px] leading-[1.85] text-landing-muted">{p}</p>
          ))}
        </Reveal>
      )}

      {about.skills.length > 0 && (
        <Reveal className="mt-10 flex flex-wrap gap-x-5 gap-y-2 items-baseline">
          <span className="label-mono">works with</span>
          <span className="font-mono text-sm text-muted-foreground">
            {about.skills.join(' · ')}
          </span>
        </Reveal>
      )}
    </div>
  )
}

