function renderInline(text: string): React.ReactNode[] {
  // bold then italics
  const nodes: React.ReactNode[] = []
  const boldParts = text.split(/\*\*(.+?)\*\*/g)
  boldParts.forEach((part, i) => {
    if (i % 2 === 1) {
      nodes.push(<strong key={`b${i}`} className="font-semibold text-foreground">{renderItalics(part)}</strong>)
    } else {
      nodes.push(renderItalics(part, `n${i}`))
    }
  })
  return nodes
}
