Cleanest small recursive splitter:

```tsx
function renderMd(text: string): React.ReactNode[] {
  const nodes: React.ReactNode[] = []
  let buffer = ''
  let i = 0
  while (i < text.length) {
    if (text.startsWith('**', i)) {
      const end = text.indexOf('**', i + 2)
      if (end !== -1) {
        if (buffer) { nodes.push(buffer); buffer = '' }
        nodes.push(<strong key={i} className="font-medium text-foreground">{text.slice(i + 2, end)}</strong>)
        i = end + 2
        continue
      }
    }
    if (text[i] === '*') {
      const end = text.indexOf('*', i + 1)
      if (end !== -1 && end !== i + 1) {
        if (buffer) { nodes.push(buffer); buffer = '' }
        nodes.push(<em key={i}>{text.slice(i + 1, end)}</em>)
        i = end + 1
        continue
      }
    }
    buffer += text[i]
    i += 1
  }
  if (buffer) nodes.push(buffer)
  return nodes
}
