'use client'

import type { ReactNode } from 'react'
import type { AboutPageDTO } from '@/lib/queries'
import Reveal from '@/components/landing/reveal'
import StackLogos from '@/components/stack-logos'

/**
 * The admin writes paragraphs in light markdown (**bold**, *italic*), so the
 * page must render it rather than print the asterisks. Inline-only by design —
 * each paragraph arrives as its own string.
 */
function renderInlineMd(text: string): ReactNode[] {
  const nodes: ReactNode[] = []
  let buffer = ''
  let i = 0

  const flush = () => {
    if (buffer) {
      nodes.push(buffer)
      buffer = ''
    }
  }

  while (i < text.length) {
    if (text.startsWith('**', i)) {
      const end = text.indexOf('**', i + 2)
      if (end !== -1) {
        flush()
        nodes.push(
          <strong key={i} className="font-semibold text-foreground">
            {text.slice(i + 2, end)}
          </strong>,
        )
        i = end + 2
        continue
      }
    }
    if (text[i] === '*') {
      const end = text.indexOf('*', i + 1)
      if (end > i + 1) {
        flush()
        nodes.push(<em key={i}>{text.slice(i + 1, end)}</em>)
        i = end + 1
        continue
      }
    }
    buffer += text[i]
    i += 1
  }

  flush()
  return nodes
}

export default function AboutLede({ about }: { about: AboutPageDTO | null }) {
  if (!about || about.paragraphs.length === 0) return null

  const paragraphs = about.paragraphs.filter(Boolean)
  if (paragraphs.length === 0) return null

  // One measured column: a serif lede, then flowing prose at reading size.
  const [lede, ...rest] = paragraphs

  return (
    <div>
      <Reveal>
        <p className="label-mono mb-10">02 / about</p>
      </Reveal>

      <div className="max-w-2xl">
        <Reveal>
          <p className="font-display text-xl sm:text-2xl leading-snug text-foreground text-pretty">
            {renderInlineMd(lede)}
          </p>
        </Reveal>

        {rest.map((p, i) => (
          <Reveal key={i} className="mt-7">
            <p className="text-[15px] sm:text-base leading-[1.9] text-landing-muted text-pretty">
              {renderInlineMd(p)}
            </p>
          </Reveal>
        ))}
      </div>

      {about.skills.length > 0 && (
        <Reveal className="mt-14 border-t border-border pt-9">
          <StackLogos skills={about.skills} />
        </Reveal>
      )}
    </div>
  )
}

