        <Reveal className="mt-14 border-t border-border pt-9">
          <StackLogos skills={about.skills} />
        </Reveal>
      )}
    </div>
  )
}

import type { CSSProperties } from 'react'

/**
 * Stack icons, self-hosted simple-icons SVGs rendered through a CSS mask so
 * they inherit the theme's ink color — monochrome at rest, primary on hover.
 * Skills without an official mark (e.g. M-Pesa Daraja API) fall back to a
 * mono text chip so the row never lies about what it can render.
 */
const STACK_ICONS: Record<string, { file: string; label: string }> = {
  'typescript': { file: 'typescript.svg', label: 'TypeScript' },
  'next.js': { file: 'nextdotjs.svg', label: 'Next.js' },
  'react': { file: 'react.svg', label: 'React' },
  'react native': { file: 'react.svg', label: 'React Native' },
  'supabase': { file: 'supabase.svg', label: 'Supabase' },
  'postgresql': { file: 'postgresql.svg', label: 'PostgreSQL' },
  'postgres': { file: 'postgresql.svg', label: 'PostgreSQL' },
  'node.js': { file: 'nodedotjs.svg', label: 'Node.js' },
  'tailwind css': { file: 'tailwindcss.svg', label: 'Tailwind CSS' },
  'turso': { file: 'turso.svg', label: 'Turso' },
}

export function StackIcon({ skill }: { skill: string }) {
  const key = skill.trim().toLowerCase()
  const icon = STACK_ICONS[key]

  if (!icon) {
    return (
      <span
        className="font-mono text-[11px] uppercase tracking-[0.14em] text-muted-foreground border border-border rounded-full px-3 py-1"
      >
        {skill}
      </span>
    )
  }

  return (
    <span className="group/icon inline-flex" title={icon.label}>
      <span
        role="img"
        aria-label={icon.label}
        className="block h-5 w-5 sm:h-6 sm:w-6 bg-muted-foreground/60 transition-all duration-300 group-hover/icon:bg-primary group-hover/icon:-translate-y-0.5"
        style={{
          WebkitMaskImage: `url(/logos/${icon.file})`,
          WebkitMaskRepeat: 'no-repeat',
          WebkitMaskPosition: 'center',
          WebkitMaskSize: 'contain',
          maskImage: `url(/logos/${icon.file})`,
          maskRepeat: 'no-repeat',
          maskPosition: 'center',
          maskSize: 'contain',
        } as CSSProperties}
      />
    </span>
  )
}

export default function StackLogos({ skills, label = 'works with' }: { skills: string[]; label?: string }) {
  if (skills.length === 0) return null

  return (
    <div className="flex flex-wrap items-center gap-x-7 gap-y-3">
      <span className="label-mono">{label}</span>
      <span className="flex flex-wrap items-center gap-x-6 gap-y-3">
        {skills.map((s) => (
          <StackIcon key={s} skill={s} />
        ))}
      </span>
    </div>
  )
}

