// Probe the stack-icon spans on the live About section + capture light-mode QA shots.
const { chromium } = require('playwright');

const BASE = 'https://kennedymuritu.vercel.app';
const OUT = '/home/pop-os/.claude/jobs/926d7900/tmp/shots';

(async () => {
  const browser = await chromium.launch();

  // ---- 1. Icon measurement (dark default) ----
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await page.goto(BASE, { waitUntil: 'networkidle' });
  // Scroll the about section into view so Reveals fire, then settle.
  await page.locator('#about').scrollIntoViewIfNeeded();
  await page.waitForTimeout(2000);

  const probe = await page.evaluate(() => {
    const spans = [...document.querySelectorAll('span[role="img"][aria-label]')];
    const maskEntries = performance.getEntriesByType('resource')
      .filter(e => e.name.includes('/logos/'))
      .map(e => ({ file: e.name.split('/logos/')[1], ms: Math.round(e.responseEnd), size: e.transferSize }));
    return {
      count: spans.length,
      icons: spans.map(s => {
        const r = s.getBoundingClientRect();
        const cs = getComputedStyle(s);
        return {
          label: s.getAttribute('aria-label'),
          w: Math.round(r.width), h: Math.round(r.height),
          bg: cs.backgroundColor,
          mask: (cs.maskImage || cs.webkitMaskImage || '').slice(0, 60),
        };
      }),
      chips: [...document.querySelectorAll('span.font-mono')].map(c => c.textContent.trim()).slice(0, 10),
      maskResources: maskEntries,
    };
  });
  console.log(JSON.stringify(probe, null, 2));

  const row = page.locator('#about');
  await row.screenshot({ path: `${OUT}/icons-dark-row.png` });

  // ---- 2. Real light mode via next-themes localStorage ----
  const light = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const lp = await light.newPage();
  await lp.addInitScript(() => localStorage.setItem('theme', 'light'));
  await lp.goto(BASE, { waitUntil: 'networkidle' });
  await lp.waitForTimeout(1200);
  const isLight = await lp.evaluate(() =>
    document.documentElement.classList.contains('dark') ? 'DARK' : 'LIGHT');
  console.log('theme after localStorage=light:', isLight);

  for (const [name, sel] of [['light-about', '#about'], ['light-work', '#work'], ['light-contact', '#contact']]) {
    const el = page.locator(sel); // wrong page ref guard
  }
  for (const [name, sel] of [['light-about', '#about'], ['light-work', '#work'], ['light-contact', '#contact']]) {
    const el = lp.locator(sel);
    await el.scrollIntoViewIfNeeded();
    await lp.waitForTimeout(1500);
    await el.screenshot({ path: `${OUT}/qa-${name}.png` });
    console.log('shot', name, 'ok');
  }
  // Skills row in light, close-up
  await lp.locator('#about').scrollIntoViewIfNeeded();
  await lp.waitForTimeout(800);
  await lp.locator('#about').screenshot({ path: `${OUT}/icons-light-row.png` });

  await browser.close();
  console.log('PROBE DONE');
})().catch(e => { console.error('FAIL', e.message); process.exit(1); });

