  return n < 10 ? `0${n}` : `${n}`
}

export default function WorkGrid({ projects }: { projects: ProjectDTO[] }) {
  const [openId, setOpenId] = useState<string | null>(null)
  const open = projects.find((p) => p.id === openId) ?? null

  // Esc closes the expanded case; page scroll locks while open.
  useEffect(() => {
    if (!open) return
    const onKey = (e: KeyboardEvent) => e.key === 'Escape' && setOpenId(null)
    document.addEventListener('keydown', onKey)
    document.body.style.overflow = 'hidden'
    return () => {
      document.removeEventListener('keydown', onKey)
      document.body.style.overflow = ''
    }
  }, [open])

  if (projects.length === 0) return null

  return (
    <>
      <motion.div
        className="grid sm:grid-cols-2 lg:grid-cols-3 gap-5"
        initial="hidden"
        whileInView="visible"
        viewport={{ once: true, margin: '-60px' }}
        variants={{ visible: { transition: { staggerChildren: 0.055, delayChildren: 0.06 } } }}
      >
        {projects.map((project, i) => (
          <motion.button
            key={project.id}
            type="button"
            layoutId={`project-${project.id}`}
            onClick={() => setOpenId(project.id)}
            variants={{
              hidden: { opacity: 0, y: 12, filter: 'blur(5px)' },
              visible: { opacity: 1, y: 0, filter: 'blur(0px)', transition: { duration: 0.48, bounce: 0.14 } },
            }}
            className="group relative text-left rounded-[24px] border border-border bg-card overflow-hidden shadow-sm transition-shadow duration-500 hover:shadow-lg focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background"
            aria-label={`${project.title} — open details`}
          >
            <div className="relative h-40 overflow-hidden">
              {project.imageUrl ? (
                <Image
                  src={project.imageUrl}
                  alt=""
                  fill
                  sizes="(max-width: 640px) 100vw, (max-width: 1024px) 50vw, 33vw"
                  className="object-cover transition-transform duration-700 group-hover:scale-105"
                />
              ) : (
                <>
                  <div
                    aria-hidden
                    className="absolute inset-0"
                    style={{ background: 'var(--gradient-bg-light)' }}
                  />
                  <div aria-hidden className="absolute inset-0 rule-grid opacity-60" />
                  <span
                    aria-hidden
                    className="absolute inset-0 flex items-center justify-center font-display font-medium text-7xl text-[color-mix(in_srgb,var(--muted)_70%,transparent)] select-none"
                  >
                    {pad(i + 1)}
                  </span>
                </>
              )}
              {/* Status pin, top-right */}
              <span className="absolute top-3 right-3 pill pill-outline text-[10px] font-mono uppercase tracking-widest backdrop-blur-sm">
                {project.statusLabel || project.status}
              </span>
              {/* Index tab, bottom-left */}
              <span className="absolute bottom-0 left-6 rounded-t-xl border border-b-0 border-border bg-background px-3 pt-1 pb-0.5 font-mono text-xs text-muted-foreground">
                {pad(i + 1)}
              </span>
            </div>

            <div className="p-5">
              <h3 className="font-display font-semibold text-lg tracking-tight line-clamp-1">
                {project.title}
              </h3>
              <p className="text-sm text-landing-muted leading-relaxed mt-2 line-clamp-2">
                {project.description}
              </p>
              <span className="mt-4 inline-flex items-center gap-1 text-xs font-mono text-primary opacity-0 translate-y-2 transition-all duration-300 group-hover:opacity-100 group-hover:translate-y-0">
                open <ArrowUpRight size={12} />
              </span>
            </div>
          </motion.button>
        ))}
      </motion.div>

      <AnimatePresence>
        {open && (
          <motion.div
            key="backdrop"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => setOpenId(null)}
            className="fixed inset-0 z-[60] bg-[color-mix(in_srgb,var(--background)_60%,transparent)] backdrop-blur-sm flex items-center justify-center p-4 sm:p-8"
            role="dialog"
            aria-modal="true"
            aria-label={open.title}
          >
            <motion.div
              layoutId={`project-${open.id}`}
              transition={{ duration: 0.35 }}
              className="relative w-full max-w-3xl max-h-[88vh] overflow-y-auto rounded-[24px] border border-border bg-card shadow-xl"
              onClick={(e) => e.stopPropagation()}
            >
              <button
                type="button"
                onClick={() => setOpenId(null)}
                aria-label="Close"
                className="absolute top-4 right-4 z-10 interactive-min p-2 rounded-full border border-border bg-background/80 backdrop-blur-sm text-muted-foreground hover:text-primary transition-colors"
              >
                <X size={16} />
              </button>

              <div className="relative h-52 overflow-hidden rounded-t-[24px]">
                {open.imageUrl ? (
                  <Image src={open.imageUrl} alt="" fill sizes="(max-width: 768px) 100vw, 768px" className="object-cover" />
                ) : (
                  <>
                    <div aria-hidden className="absolute inset-0" style={{ background: 'var(--gradient-bg-light)' }} />
                    <div aria-hidden className="absolute inset-0 rule-grid opacity-60" />
                  </>
                )}
              </div>

              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1, transition: { delay: 0.15, duration: 0.4 } }}
                className="p-6 sm:p-9"
              >
                <p className="label-mono mb-3">
                  {pad(projects.indexOf(open) + 1)} / {open.category}
                  {' · '}
                  {open.statusLabel || open.status}
                </p>
                <h3 className="font-display text-2xl sm:text-3xl font-semibold tracking-tight">
                  {open.title}
                </h3>
                <p className="text-landing-muted leading-relaxed mt-4">{open.longDescription || open.description}</p>

                {(open.problem || open.solution) && (
                  <div className="grid sm:grid-cols-2 gap-5 mt-8">
                    {open.problem && (
                      <div>
                        <p className="label-mono mb-2">the problem</p>
                        <p className="text-sm text-landing-muted leading-relaxed">{open.problem}</p>
                      </div>
                    )}
                    {open.solution && (
                      <div>
                        <p className="label-mono mb-2">the build</p>
                        <p className="text-sm text-landing-muted leading-relaxed">{open.solution}</p>
                      </div>
                    )}
                  </div>
                )}

                {open.tech.length > 0 && (
                  <div className="flex flex-wrap gap-2 mt-8">
                    {open.tech.map((t) => (
                      <span key={t} className="stack-tag">{t}</span>
                    ))}
                  </div>
                )}

                {open.myRole && (
                  <p className="text-xs font-mono text-muted-foreground mt-6 leading-relaxed">{open.myRole}</p>
                )}

                {(open.liveUrl || open.githubUrl) && (
                  <div className="flex flex-wrap gap-3 mt-8">
                    {open.liveUrl && (
                      <a href={open.liveUrl} target="_blank" rel="noopener noreferrer" className="btn-primary !py-2.5 text-sm">
                        Visit live
                      </a>
                    )}
                    {open.githubUrl && (
                      <a href={open.githubUrl} target="_blank" rel="noopener noreferrer" className="btn-ghost !py-2.5 text-sm inline-flex items-center gap-1.5">
                        Code <ArrowUpRight size={14} />
                      </a>
                    )}
                  </div>
                )}

                <Link
                  href="/essays"
                  className="mt-8 inline-flex items-center gap-1.5 text-sm font-mono text-primary hover:underline"
                >
                  read how builds like this happen <ArrowUpRight size={13} />
                </Link>
              </motion.div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  )
}

