'use client'

import { useState } from 'react'
import { Coffee, Loader2, CheckCircle, AlertCircle } from 'lucide-react'
import { PRESET_AMOUNTS } from '@/lib/payments/coffee-presets'

type Status = 'idle' | 'sending' | 'polling' | 'success' | 'error'

export default function BuyCoffeeSection() {
  const [amount, setAmount] = useState<number>(200)
  const [customAmount, setCustomAmount] = useState('')
  const [phone, setPhone] = useState('')
  const [donorName, setDonorName] = useState('')
  const [message, setMessage] = useState('')
  const [status, setStatus] = useState<Status>('idle')
  const [errorMsg, setErrorMsg] = useState('')

  const resolvedAmount = customAmount ? Number(customAmount) : amount

  const pollStatus = async (ref: string) => {
    for (let i = 0; i < 30; i++) {
      await new Promise((r) => setTimeout(r, 2000))
      const res = await fetch(`/api/coffee/status?ref=${encodeURIComponent(ref)}`)
      if (!res.ok) continue
      const data = (await res.json()) as { status: string }
      if (data.status === 'completed') {
        setStatus('success')
        return
      }
      if (data.status === 'failed') {
        setStatus('error')
        setErrorMsg('Payment failed or was cancelled.')
        return
      }
    }
    setStatus('error')
    setErrorMsg('Payment timed out. Check M-Pesa or try again.')
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!phone || resolvedAmount < 50) return
    setStatus('sending')
    setErrorMsg('')

    try {
      const res = await fetch('/api/coffee/initiate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          phone,
          amountKes: resolvedAmount,
          donorName: donorName || undefined,
          message: message || undefined,
        }),
      })
      const data = await res.json()
      if (!res.ok) {
        setStatus('error')
        setErrorMsg(data.error ?? 'Could not start payment')
        return
      }
      setStatus('polling')
      await pollStatus(data.reference)
    } catch {
      setStatus('error')
      setErrorMsg('Something went wrong. Try again.')
    }
  }

  if (status === 'success') {
    return (
      <div className="rounded-xl border border-border bg-card p-6 text-center">
        <CheckCircle className="mx-auto text-primary mb-3" size={32} />
        <p className="font-display font-semibold text-foreground">Asante! Payment received.</p>
        <p className="text-sm text-muted-foreground mt-1">Your support keeps the builds going.</p>
      </div>
    )
  }

  return (
    <div className="rounded-xl border border-border bg-card p-6">
      <div className="flex items-center gap-2 mb-4">
        <Coffee size={18} className="text-primary" />
        <h4 className="font-display font-semibold text-foreground">Buy me a coffee</h4>
      </div>
      <p className="text-sm text-muted-foreground mb-4">
        Support via M-Pesa STK push (Kenya). Choose an amount or enter your own.
      </p>

      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="flex flex-wrap gap-2">
          {PRESET_AMOUNTS.map((a) => (
            <button
              key={a}
              type="button"
              onClick={() => {
                setAmount(a)
                setCustomAmount('')
              }}
              className={`px-4 py-2 rounded-lg text-sm font-mono border transition-colors ${
                amount === a && !customAmount
                  ? 'border-primary bg-primary/10 text-primary'
                  : 'border-border text-muted-foreground hover:border-primary/40'
              }`}
            >
              KES {a}
            </button>
          ))}
        </div>

        <input
          type="number"
          min={50}
          max={5000}
          placeholder="Custom amount (KES)"
          value={customAmount}
          onChange={(e) => setCustomAmount(e.target.value)}
          className="w-full px-3 py-2.5 bg-background border border-border rounded text-sm"
        />

        <input
          type="tel"
          required
          placeholder="M-Pesa phone (07XXXXXXXX)"
          value={phone}
          onChange={(e) => setPhone(e.target.value)}
          className="w-full px-3 py-2.5 bg-background border border-border rounded text-sm"
        />
        <input
          type="text"
          placeholder="Your name (optional)"
          value={donorName}
          onChange={(e) => setDonorName(e.target.value)}
          className="w-full px-3 py-2.5 bg-background border border-border rounded text-sm"
        />
        <input
          type="text"
          placeholder="Short note (optional)"
          value={message}
          onChange={(e) => setMessage(e.target.value)}
          className="w-full px-3 py-2.5 bg-background border border-border rounded text-sm"
        />

        {status === 'error' && (
          <div className="flex items-center gap-2 text-destructive text-sm">
            <AlertCircle size={14} />
            {errorMsg}
          </div>
        )}

        <button
          type="submit"
          disabled={status === 'sending' || status === 'polling'}
          className="btn-primary w-full justify-center flex items-center gap-2 disabled:opacity-50"
        >
          {(status === 'sending' || status === 'polling') && (
            <Loader2 size={14} className="animate-spin" />
          )}
          {status === 'polling' ? 'Waiting for M-Pesa…' : 'Pay with M-Pesa'}
        </button>
      </form>
    </div>
  )
}

import type { CSSProperties } from 'react'

/**
 * Stack icons, self-hosted simple-icons SVGs rendered through a CSS mask so
 * they inherit the theme's ink color — monochrome at rest, primary on hover.
 * Skills without an official mark (e.g. M-Pesa Daraja API) fall back to a
 * mono text chip so the row never lies about what it can render.
 */
const STACK_ICONS: Record<string, { file: string; label: string }> = {
  'typescript': { file: 'typescript.svg', label: 'TypeScript' },
  'next.js': { file: 'nextdotjs.svg', label: 'Next.js' },
  'react': { file: 'react.svg', label: 'React' },
  'react native': { file: 'react.svg', label: 'React Native' },
  'supabase': { file: 'supabase.svg', label: 'Supabase' },
  'postgresql': { file: 'postgresql.svg', label: 'PostgreSQL' },
  'postgres': { file: 'postgresql.svg', label: 'PostgreSQL' },
  'node.js': { file: 'nodedotjs.svg', label: 'Node.js' },
  'tailwind css': { file: 'tailwindcss.svg', label: 'Tailwind CSS' },
  'turso': { file: 'turso.svg', label: 'Turso' },
}

export function StackIcon({ skill }: { skill: string }) {
  const key = skill.trim().toLowerCase()
  const icon = STACK_ICONS[key]

  if (!icon) {
    return (
      <span
        className="font-mono text-[11px] uppercase tracking-[0.14em] text-muted-foreground border border-border rounded-full px-3 py-1"
      >
        {skill}
      </span>
    )
  }

  return (
    <span className="group/icon inline-flex" title={icon.label}>
      <span
        role="img"
        aria-label={icon.label}
        // The theme colors are plain hex vars, so Tailwind's /opacity
        // modifiers generate nothing — blend via color-mix instead.
        className="block h-5 w-5 sm:h-6 sm:w-6 bg-[color-mix(in_srgb,var(--muted-foreground)_60%,transparent)] transition-all duration-300 group-hover/icon:bg-primary group-hover/icon:-translate-y-0.5"
        style={{
          WebkitMaskImage: `url(/logos/${icon.file})`,
          WebkitMaskRepeat: 'no-repeat',
          WebkitMaskPosition: 'center',
          WebkitMaskSize: 'contain',
          maskImage: `url(/logos/${icon.file})`,
          maskRepeat: 'no-repeat',
          maskPosition: 'center',
          maskSize: 'contain',
        } as CSSProperties}
      />
    </span>
  )
}

export default function StackLogos({ skills, label = 'works with' }: { skills: string[]; label?: string }) {
  if (skills.length === 0) return null

  return (
    <div className="flex flex-wrap items-center gap-x-7 gap-y-3">
      <span className="label-mono">{label}</span>
      <span className="flex flex-wrap items-center gap-x-6 gap-y-3">
        {skills.map((s) => (
          <StackIcon key={s} skill={s} />
        ))}
      </span>
    </div>
  )
}

