// Verify icons + modal scrim + light theme on the LOCAL production build.
const { chromium } = require('playwright');
const OUT = '/home/pop-os/.claude/jobs/926d7900/tmp/shots';
const BASE = 'http://localhost:3111';

(async () => {
  const browser = await chromium.launch();

  // Dark (default)
  const d = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  await d.goto(BASE, { waitUntil: 'networkidle' });
  await d.locator('#about').scrollIntoViewIfNeeded();
  await d.waitForTimeout(2200);
  const icons = await d.evaluate(() =>
    [...document.querySelectorAll('span[role="img"][aria-label]')].map(s => {
      const r = s.getBoundingClientRect();
      return { label: s.getAttribute('aria-label'), w: Math.round(r.width), bg: getComputedStyle(s).backgroundColor };
    }),
  );
  console.log('DARK icons:', JSON.stringify(icons));
  await d.locator('#about').screenshot({ path: `${OUT}/fix-about-dark.png` });

  // Modal scrim check: open first work card, measure backdrop bg
  await d.locator('#work').scrollIntoViewIfNeeded();
  await d.waitForTimeout(1500);
  const card = d.locator('#work button').filter({ hasText: 'ADDPlus' }).first();
  await card.click();
  await d.waitForTimeout(900);
  const scrim = await d.evaluate(() => {
