  await d.locator('#work button').filter({ hasText: 'Caspahub' }).first().click();
  await d.waitForTimeout(1000);
  const scrim = await d.evaluate(() => {
    const el = [...document.querySelectorAll('div')].find(x => {
      const cs = getComputedStyle(x);
      return cs.position === 'fixed' && cs.zIndex === '60';
    });
    return el ? getComputedStyle(el).backgroundColor : 'not-found';
